INSERT INTO `v1_cf6e1eb6171fa818c70dbdf8a83b0d3b9583615c8a62ba6595b0873809a0cd0d` VALUES (2, "", 1, "アヤネ", 1, 1, 0, "", "---", 1);
INSERT INTO `v1_cf6e1eb6171fa818c70dbdf8a83b0d3b9583615c8a62ba6595b0873809a0cd0d` VALUES (1, "逆境に屈することなく、部員たちを引っ張る主将。ミート力を活かした安定感のある打撃が持ち味。", 3, "アサヒ", 0, 1, 6000, "", "---", 2);
INSERT INTO `v1_cf6e1eb6171fa818c70dbdf8a83b0d3b9583615c8a62ba6595b0873809a0cd0d` VALUES (3, "無愛想だが仲間を大切に想う気持ちは誰よりも強い男。ケンカで鍛えた腕っぷしが自慢のパワーヒッター。", 0, "部員3", 3, 1, 16000, "ホームランを連発すると、連発数に応じてパワーアップする", "アドレナリン", 3);
INSERT INTO `v1_cf6e1eb6171fa818c70dbdf8a83b0d3b9583615c8a62ba6595b0873809a0cd0d` VALUES (2, "みんなからの厚い信頼を集める期待の助っ人部員。実力は未知数だが幸運なハプニングを呼び込む。", 2, "{0}", 2, 1, 30000, "幸運のハプニングを呼び込む", "ラッキー", 4);
INSERT INTO `v1_cf6e1eb6171fa818c70dbdf8a83b0d3b9583615c8a62ba6595b0873809a0cd0d` VALUES (0, "みんなの知らない極秘情報がのっているおまけページ。決して誰かに見せてはいけない。", 1, "選手名鑑 おまけページ", 1, 0, 50000, "", "", 5);
